/**
 * 返回数组 a 中的最大项.
 * 假设 a.size( ) > 0.
 * 可比较的对象必须提供 operator<和 operator=
 */
template <typename Comparable>
const Comparable & findMax( const vector<Comparable> & a )
{
    int maxIndex = 0;

    for( int i = 1; i < a.size( ); ++i )
        if( a[ maxIndex ] < a[ i ] )
            maxIndex = i;
    return a[ maxIndex ];
}

