        explicit Square( double s = 0.0 ) : side{ s }
        { }

        double getSide( ) const
        { return side; }
        double getArea( ) const
        { return side * side; }
        double getPerimeter( ) const
        { return 4 * side; }

        void print( ostream & out = cout ) const
        { out << "(square " << getSide( ) << ")"; }
        bool operator< ( const Square & rhs ) const
        { return getSide( ) < rhs.getSide( ); }

